structureCode.vanilla:
const abas = createTabs({
  defaultValue: 'overview',
  variant: 'default',            // default (trilho) | line (indicador)
  orientation: 'horizontal',     // horizontal | vertical
  // Obrigatório: nomeia a lista de abas, que é o que o leitor de tela anuncia.
  'aria-label': 'Seções',
  items: [
    { value: 'overview',   label: 'Visão geral',  content: painelVisaoGeral },
    { value: 'properties', label: 'Propriedades', content: painelPropriedades },
    { value: 'examples',   label: 'Exemplos',     content: painelExemplos },
  ],
  onValueChange: (valor) => console.log(valor),
});

extensibilityCode.react:
// Tabs controladas com analytics
const [value, setValue] = useState('overview');

<Tabs
  value={value}
  onValueChange={(next) => {
    track('tab_change', {
      component: 'tabs',
      label: tabs.find((t) => t.value === next)?.label,
      index: tabs.findIndex((t) => t.value === next),
      total: tabs.length,
    });
    setValue(next);
  }}
>
  <TabsList aria-label="Seções do componente">
    {tabs.map((t) => (
      <TabsTrigger key={t.value} value={t.value}>{t.label}</TabsTrigger>
    ))}
  </TabsList>
  {tabs.map((t) => (
    <TabsContent key={t.value} value={t.value}>{t.content}</TabsContent>
  ))}
</Tabs>

